p=f/'qa/neutral_section_evidence.json';e=json.loads(p.read_text());assert e['input_export_sha256']==sha(f/'exports/AST-RTL-001.glb')and e['input_source_sha256']==sha(f/'source/AST-RTL-001.blend')and e['script_sha256']==sha(f/'qa/draw_neutral_section.py');captures.append({'receipt':bind(p),'section_script':bind(f/'qa/draw_neutral_section.py'),'mesh_derived_section':True});add_image(f/e['image'],e['image_sha256'],'actual_native_triangle_section_neutral','Mesh cut visibly connects sole/plinth, open storage, main work slab, upper shelf, back and stepped canopy. It is component geometry, not a recovered room section')
