for name,h in r['inputs_before'].items():assert sha(ROOT/name)==h;inputs.append(bind(ROOT/name))
comments={'003_guest_standing_640':'Raised public parcel rest and lower clear wrapping top are distinct at ordinary height; identity is an original parcel graphic and the grounded open structure remains clear','003_staff_work_1280':'Rear stock shelves, supported divided lower access and uninterrupted wrapping top explain the work side; inactive control face does not imply transactions','004_closed_detail_1280':'Coherent pale lid, warm faceted case, ribs and supported top grip; visible closure is a removable fitted lid, not an operating latch','004_open_lid_parked_1280':'Actual hollow case, nested divided carrier and independently parked lid are visible; empty volume is not supplied inventory','004_detached_handling_1280':'Tray is deliberately suspended as an externally held handling state; hollow shell and supports are visible. Must not be captioned as self-supporting','004_on_guest_rest_standing_640':'Closed repeated case rests on public parcel surface while broad wrapping top remains useful and clear'}
